CREATE TABLE accounting_cost_code_mappings (cost_code_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,account_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_accounting_cost_mapping_account(account_id),CONSTRAINT fk_accounting_cost_mapping_cost_code FOREIGN KEY(cost_code_id) REFERENCES cost_codes(id) ON DELETE RESTRICT,CONSTRAINT fk_accounting_cost_mapping_account FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
